[
  {
    "title": "neutral-stance-not-explained",
    "claim": "Image #2 asks for one stance input plus one technique input, while Image #6 shows Lunge Punch using the standing dot plus forward without explicitly saying to leave the stance stick centered.",
    "reason": "A newcomer could interpret the opening instruction as requiring both sticks to be pushed.",
    "suggest": "Change the instruction to: 'Choose a stance—leave STANCE centered for standing—then push TECHNIQUE.'"
  },
  {
    "title": "countdown-competes-with-instructions",
    "claim": "Image #2 displays 'STARTING IN 5' beneath FIGHT while the opponent description and control instructions remain visible.",
    "reason": "This communicates a deadline for reading; the still cannot establish whether the fight actually starts automatically.",
    "suggest": "Replace the introductory countdown with 'Start when ready'; verify its behavior and require an explicit FIGHT action on this instructional card."
  },
  {
    "title": "score-calls-need-plain-language",
    "claim": "Images #17 and #20 display IPPON and WAZA-ARI respectively, but neither call banner includes 'full point' or 'half point'.",
    "reason": "Players unfamiliar with karate terminology must interpret the HUD score instead of learning the award directly from the prominent announcement.",
    "suggest": "Keep the karate terms and add 'Full point' beneath IPPON and 'Half point' beneath WAZA-ARI."
  },
  {
    "title": "desktop-bindings-not-visible",
    "claim": "Image #9 labels the two desktop joysticks STANCE and TECHNIQUE but shows no keyboard key bindings for either.",
    "reason": "A keyboard player cannot discover the corresponding keys from the visible play screen.",
    "suggest": "Display the actual configured keyboard bindings beside each joystick label on desktop, without displacing the primary touch controls."
  },
  {
    "title": "fighter-label-size-unverified",
    "claim": "I cannot determine whether the visible fighter-name labels in Images #3 and #9 satisfy the required 18 CSS px minimum from these raster frames.",
    "reason": "Those names identify the competitors, and screenshot pixels alone do not establish their rendered CSS sizing.",
    "suggest": "Measure their computed font sizes and applied scaling at the phone and desktop viewports; enlarge any verified undersized labels and reflow the scoreboard rather than shrinking the text."
  }
]
